"""Merge k Sorted Lists — min-heap over the k current heads.

The index in the tuple breaks ties so Python never has to compare ListNodes.

Time: O(N log k)   Space: O(k)
"""
import heapq

if "ListNode" not in globals():
    class ListNode:
        def __init__(self, val=0, next=None):
            self.val = val
            self.next = next


class Solution:
    def mergeKLists(self, lists):
        heap = []
        for i, node in enumerate(lists):
            if node:
                heapq.heappush(heap, (node.val, i, node))
        sentinel = ListNode()
        tail = sentinel
        while heap:
            _, i, node = heapq.heappop(heap)
            tail.next = node
            tail = node
            if node.next:
                heapq.heappush(heap, (node.next.val, i, node.next))
        tail.next = None
        return sentinel.next
